<?php/** * Service: Content Declaration (Classify) — V1.0.4 *  * Supports: Posts, Pages, WooCommerce Products, Custom Post Types, Media * Fully Local Storage. * @package MegaGovern * @since   1.0.4 */namespace MegaGovern;if ( ! defined( 'ABSPATH' ) ) {    exit;}/** * Class Declaration *  * Handles content declaration for AI transparency. */class Declaration {    /**     * Valid declaration types.     *     * @var array     */    private const VALID_TYPES = array( 'human', 'ai_assisted', 'ai_generated', 'deepfake' );    /**     * Lucide icon mapping (No Dashicons).     *     * @var array     */    private const TYPE_ICONS = array(        'human'        => 'lucide-user',        'ai_assisted'  => 'lucide-pencil',        'ai_generated' => 'lucide-brain',        'deepfake'     => 'lucide-scan',    );    /**     * Color mapping for declaration types.     *     * @var array     */    private const TYPE_COLORS = array(        'human'        => '#2271b1',        'ai_assisted'  => '#dba617',        'ai_generated' => '#d63638',        'deepfake'     => '#d63638',    );    /**     * CSS class mapping for declaration types.     *     * @var array     */    private const TYPE_CSS = array(        'human'        => 'mga-status-human',        'ai_assisted'  => 'mga-status-ai-modified',        'ai_generated' => 'mga-status-ai-generated',        'deepfake'     => 'mga-status-deepfake',    );    /**     * EU SVG icons mapping (used by Labels.php).     *     * @var array     */    private const TYPE_SVG = array(        'human'        => '',        'ai_assisted'  => 'partially-ai',        'ai_generated' => 'fully-ai',        'deepfake'     => 'fully-ai',    );    // ═══════════════════════════════════════    // TRANSLATED GETTERS (i18n)    // ═══════════════════════════════════════    /**     * Get translated label for a declaration type.     *     * @param string $type Declaration type.     * @return string Translated label.     */    public static function get_type_label( string $type ): string {        $labels = array(            'human'        => __( 'Human Made', 'megagovern' ),            'ai_assisted'  => __( 'AI Modified', 'megagovern' ),            'ai_generated' => __( 'Fully AI-Generated', 'megagovern' ),            'deepfake'     => __( 'Synthetic Media', 'megagovern' ),        );        return isset( $labels[ $type ] ) ? $labels[ $type ] : $type;    }    /**     * Get translated alt text for a declaration type.     *     * @param string $type Declaration type.     * @return string Translated alt text.     */    public static function get_alt_text( string $type ): string {        $alt = array(            'human'        => __( 'Content created by a human', 'megagovern' ),            'ai_assisted'  => __( 'AI Modified content - AI was used to modify pre-existing human content', 'megagovern' ),            'ai_generated' => __( 'Fully AI-Generated content - No human editorial control', 'megagovern' ),            'deepfake'     => __( 'AI Generated or manipulated content (Synthetic Media) - May not be authentic', 'megagovern' ),        );        return isset( $alt[ $type ] ) ? $alt[ $type ] : '';    }    // ═══════════════════════════════════════    // CONSTRUCTOR    // ═══════════════════════════════════════    /**     * Constructor.     */    public function __construct() {        add_action( 'add_meta_boxes', array( $this, 'add_meta_box' ) );        add_action( 'save_post', array( $this, 'save_declaration' ) );        add_action( 'save_post', array( $this, 'check_legacy_exempt' ), 20, 3 );        add_action( 'admin_footer', array( $this, 'enforce_declaration_js' ) );        add_action( 'save_post_product', array( $this, 'save_declaration' ) );        add_action( 'save_post_product', array( $this, 'check_legacy_exempt' ), 20, 3 );        add_action( 'wp_ajax_megagovern_single_declare', array( $this, 'ajax_single_declare' ) );        add_action( 'megagovern_declaration_changed', array( $this, 'on_declaration_changed' ), 10, 4 );    }    // ═══════════════════════════════════════    // POST TYPES    // ═══════════════════════════════════════    /**     * Get supported post types for declarations.     *     * @return array     */    private function get_supported_post_types(): array {        $saved   = get_option( 'megagovern_declaration_post_types', array( 'post', 'page' ) );        $all     = get_post_types( array( 'public' => true ), 'names' );        $exclude = array( 'attachment', 'revision', 'nav_menu_item', 'custom_css', 'customize_changeset' );        $types = array_intersect( (array) $saved, $all );        $types = array_diff( $types, $exclude );        if ( class_exists( 'WooCommerce' ) ) {            $types[] = 'product';        }        $types = array_unique( $types );        return empty( $types ) ? array( 'post', 'page' ) : array_values( $types );    }    // ═══════════════════════════════════════    // META BOX    // ═══════════════════════════════════════    /**     * Add meta box to supported post types.     */    public function add_meta_box(): void {        $post_types = $this->get_supported_post_types();        add_meta_box(            'megagovern_declaration',            __( 'EU AI Act Declaration', 'megagovern' ),            array( $this, 'render_meta_box' ),            $post_types,            'side',            'high'        );    }    /**     * Render meta box content.     *     * @param WP_Post $post Current post object.     */    public function render_meta_box( $post ): void {        $current = get_post_meta( $post->ID, '_megagovern_declaration', true );        wp_nonce_field( 'megagovern_declaration_save', 'megagovern_declaration_nonce' );        ?>        <div class="megagovern-declaration-box">            <p style="margin: 0 0 10px; font-weight: 600; color: #1d2327;">                <?php esc_html_e( 'Select content source (EU AI Act Art. 50):', 'megagovern' ); ?>            </p>            <?php foreach ( self::VALID_TYPES as $type ) :                 $svg_key = self::TYPE_SVG[ $type ] ?? '';                $svg_url = ! empty( $svg_key ) ? MEGAGOVERN_URL . 'assets/images/eu-icons/' . $svg_key . '/' . $svg_key . '-black.svg' : '';                $svg_path = ! empty( $svg_key ) ? MEGAGOVERN_PATH . 'assets/images/eu-icons/' . $svg_key . '/' . $svg_key . '-black.svg' : '';                $has_svg = ! empty( $svg_path ) && file_exists( $svg_path );            ?>                <label style="display: block; margin-bottom: 8px; cursor: pointer; padding: 6px 8px; border-radius: 4px; <?php echo $current === $type ? 'background: #f0f6fc; border-left: 3px solid ' . esc_attr( self::TYPE_COLORS[ $type ] ) . ';' : ''; ?>">                    <input                        type="radio"                        name="megagovern_declaration"                        value="<?php echo esc_attr( $type ); ?>"                        <?php checked( $current, $type ); ?>                        style="margin-right: 6px;"                        aria-label="<?php echo esc_attr( self::get_alt_text( $type ) ); ?>"                    >                    <?php if ( $has_svg ) : ?>                        <img src="<?php echo esc_url( $svg_url ); ?>"                              alt="<?php echo esc_attr( self::get_alt_text( $type ) ); ?>"                             style="width: 20px; height: 20px; vertical-align: middle; margin-right: 4px;">                    <?php else : ?>                        <span style="display: inline-block; width: 12px; height: 12px; border-radius: 50%; background: <?php echo esc_attr( self::TYPE_COLORS[ $type ] ); ?>; vertical-align: middle; margin-right: 6px;"></span>                    <?php endif; ?>                    <?php echo esc_html( self::get_type_label( $type ) ); ?>                    <?php if ( $type !== 'human' ) : ?>                        <span style="font-size: 9px; color: #646970; display: block; margin-left: 24px;">                            <?php echo esc_html( self::get_alt_text( $type ) ); ?>                        </span>                    <?php endif; ?>                </label>            <?php endforeach; ?>            <?php if ( ! empty( $current ) ) : ?>                <div style="margin-top: 10px; padding: 6px 10px; background: #f0f0f1; border-radius: 4px; font-size: 11px; color: #50575e;">                    <em>                        <?php                        /* translators: %s: current declaration type label (e.g., Human Made, AI Generated) */                        printf( esc_html__( 'Current: %s', 'megagovern' ), esc_html( self::get_type_label( $current ) ) );                        ?>                    </em>                </div>                <?php                // Snapshot status indicator — shows if declared_at exists                $snapshot_date = get_post_meta( $post->ID, '_megagovern_declared_at', true );                if ( $snapshot_date ) :                ?>                    <div style="margin-top: 6px; padding: 4px 10px; background: #edfaef; border-left: 3px solid #00a32a; border-radius: 2px; font-size: 10px; color: #1e7a34;">                        <span style="font-weight:600;">● <?php esc_html_e( 'Snapshot captured', 'megagovern' ); ?></span>                        <span style="color: #50575e; margin-left: 4px;">                            <?php echo esc_html( gmdate( 'M j, Y — H:i', strtotime( $snapshot_date ) ) ); ?>                        </span>                    </div>                <?php endif; ?>            <?php endif; ?>            <p style="margin-top: 10px; color: #646970; font-size: 11px; font-style: italic;">                <?php esc_html_e( 'Required before publishing — EU AI Act Art. 50', 'megagovern' ); ?>            </p>        </div>        <?php    }    // ═══════════════════════════════════════    // SAVE DECLARATION (META BOX)    // ═══════════════════════════════════════    /**     * Save declaration from meta box.     *     * @param int $post_id Post ID.     */    public function save_declaration( $post_id ): void {        if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) {            return;        }        if ( ! isset( $_POST['megagovern_declaration_nonce'] ) ) {            return;        }        if ( ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['megagovern_declaration_nonce'] ) ), 'megagovern_declaration_save' ) ) {            return;        }        if ( ! current_user_can( 'edit_post', $post_id ) ) {            return;        }        if ( ! isset( $_POST['megagovern_declaration'] ) ) {            return;        }        $type    = sanitize_text_field( wp_unslash( $_POST['megagovern_declaration'] ) );        $user_id = get_current_user_id();        self::declare( $post_id, $type, $user_id, 'meta_box' );    }    // ═══════════════════════════════════════    // STATIC DECLARE — SINGLE SOURCE OF TRUTH    // ═══════════════════════════════════════    /**     * Programmatic declaration — the single save path for all contexts.     *     * Used by: meta box, AJAX single declare, Scanner bulk apply,     * and any future service that needs to set a declaration.     *     * @param int    $post_id Post ID.     * @param string $type    One of VALID_TYPES.     * @param int    $user_id User ID making the declaration.     * @param string $context Context label for audit trail.     * @return bool  True on success.     */    public static function declare( int $post_id, string $type, int $user_id, string $context = 'manual' ): bool {        if ( ! in_array( $type, self::VALID_TYPES, true ) ) {            return false;        }        $post = get_post( $post_id );        if ( ! $post ) {            return false;        }        if ( ! current_user_can( 'edit_post', $post_id ) ) {            return false;        }        $previous     = get_post_meta( $post_id, '_megagovern_declaration', true );        $content_hash = self::generate_content_hash( $post_id );        $now          = current_time( 'mysql' );        // Save all postmeta        update_post_meta( $post_id, '_megagovern_declaration', $type );        update_post_meta( $post_id, '_megagovern_declared_by', $user_id );        update_post_meta( $post_id, '_megagovern_declared_at', $now );        update_post_meta( $post_id, '_megagovern_content_hash', $content_hash );        // Fire hooks for Evidence snapshots and other listeners        do_action( 'megagovern_after_declaration', $post_id, $now );        do_action( 'megagovern_declaration_changed', $post_id, $type, $previous, $user_id );        // Log to declaration log table        $instance = new self();        $instance->log_to_new_table( $post_id, $type, $user_id, $previous );        // Log via Governance (if exists)        if ( class_exists( '\MegaGovern\Governance' ) ) {            if ( empty( $previous ) ) {                Governance::log_action( 'classified', $post_id, $type, $user_id, array(                    'context' => $context,                ) );            } elseif ( $previous !== $type ) {                Governance::log_action( 'reclassified', $post_id, $type, $user_id, array(                    'previous_type' => $previous,                    'context'       => $context,                ) );            }        }        return true;    }    // ═══════════════════════════════════════    // LEGACY ARCHIVE AUTO-EXEMPT    // ═══════════════════════════════════════    /**     * Check if a post should be automatically exempt from AI Act declarations     * based on its publish date being before the cutoff date.     *     * @param int     $post_id Post ID.     * @param \WP_Post $post    Post object.     * @param bool    $update  Whether this is an update.     */    public function check_legacy_exempt( int $post_id, \WP_Post $post, bool $update ): void {        // Skip if already has a declaration        $declaration = get_post_meta( $post_id, '_megagovern_declaration', true );        if ( ! empty( $declaration ) ) {            return;        }        // Skip if already marked as exempt        $exempt = get_post_meta( $post_id, '_megagovern_legacy_exempt', true );        if ( '1' === $exempt ) {            return;        }        // Skip if revoked        $revoked = get_post_meta( $post_id, '_megagovern_exempt_revoked', true );        if ( '1' === $revoked ) {            return;        }        // Check if Archive class exists        if ( ! class_exists( '\MegaGovern\Archive' ) ) {            return;        }        // Get post date        $post_date = get_post_time( 'Y-m-d', true, $post_id );        if ( ! $post_date ) {            return;        }        // Get cutoff date        $cutoff = Archive::get_cutoff_date();        // If post is before cutoff, mark as exempt        if ( $post_date < $cutoff ) {            update_post_meta( $post_id, '_megagovern_legacy_exempt', '1' );            // Log the auto-exemption            if ( class_exists( '\MegaGovern\Governance' ) ) {                Governance::log_action(                    'legacy_exempted',                    $post_id,                    'system',                    get_current_user_id(),                    array( 'note' => __( 'Auto-exempted: published before cutoff date.', 'megagovern' ) )                );            }        }    }    // ═══════════════════════════════════════    // DECLARATION CHANGED HANDLER    // ═══════════════════════════════════════    /**     * Handle declaration changed event.     *     * @param int    $post_id  Post ID.     * @param string $new_type New declaration type.     * @param string $old_type Old declaration type.     * @param int    $user_id  User ID.     */    public function on_declaration_changed( $post_id, $new_type, $old_type, $user_id ): void {        $this->log_to_new_table( $post_id, $new_type, $user_id, $old_type );    }    // ═══════════════════════════════════════    // AJAX SINGLE DECLARE    // ═══════════════════════════════════════    /**     * AJAX handler for single declaration.     */    public function ajax_single_declare(): void {        check_ajax_referer( 'megagovern_single_declare', 'nonce' );        if ( ! current_user_can( 'edit_posts' ) ) {            wp_send_json_error( array( 'message' => __( 'Permission denied.', 'megagovern' ) ) );        }        $post_id = isset( $_POST['post_id'] ) ? intval( $_POST['post_id'] ) : 0;        $type    = isset( $_POST['type'] ) ? sanitize_text_field( wp_unslash( $_POST['type'] ) ) : '';        if ( ! $post_id || ! in_array( $type, self::VALID_TYPES, true ) ) {            wp_send_json_error( array( 'message' => __( 'Invalid data.', 'megagovern' ) ) );        }        $user_id = get_current_user_id();        $result  = self::declare( $post_id, $type, $user_id, 'ajax' );     	if ( $result ) {            wp_send_json_success( array(               'message' => sprintf(          	/* translators: %s: declaration type label (e.g., Human Made, AI Generated) */            __( 'Content declared as %s.', 'megagovern' ),            self::get_type_label( $type )                ),            ) );        } else {            wp_send_json_error( array( 'message' => __( 'Declaration failed.', 'megagovern' ) ) );        }    }    // ═══════════════════════════════════════    // CONTENT HASH GENERATION (STATIC)    // ═══════════════════════════════════════    /**     * Generate SHA-256 content hash for a post.     *     * @param int $post_id     * @return string SHA-256 hash     */    public static function generate_content_hash( int $post_id ): string {        $post = get_post( $post_id );        if ( ! $post ) {            return '';        }        $content = $post->post_content . $post->post_title . $post->post_modified;        return hash( 'sha256', $content );    }    // ═══════════════════════════════════════    // LOG TO NEW TABLE    // ═══════════════════════════════════════    /**     * Log to new declaration log table.     *     * @param int    $post_id     * @param string $type     * @param int    $user_id     * @param string $previous     * @return bool     */    private function log_to_new_table( int $post_id, string $type, int $user_id, string $previous = '' ): bool {        global $wpdb;        $table = $wpdb->prefix . 'mega_declaration_log';        // Check if Db class exists and table exists        if ( ! class_exists( '\MegaGovern\Db' ) || ! method_exists( '\MegaGovern\Db', 'log_table_exists' ) ) {            return false;        }        if ( ! Db::log_table_exists() ) {            return false;        }        $type_int = $this->type_to_int( $type );        $prev_int = $this->type_to_int( $previous );        $action   = empty( $previous ) ? 'classified' : 'reclassified';        // phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery        $result = $wpdb->insert(            $table,            array(                'post_id'          => $post_id,                'declaration_type' => $type_int,                'user_id'          => $user_id,                'action'           => $action,                'previous_type'    => $prev_int,                'logged_at'        => current_time( 'mysql' ),            ),            array( '%d', '%d', '%d', '%s', '%d', '%s' )        );        return (bool) $result;    }    /**     * Convert type string to integer.     *     * @param string $type     * @return int     */    private function type_to_int( string $type ): int {        $map = array(            'human'        => 0,            'ai_assisted'  => 1,            'ai_generated' => 2,            'deepfake'     => 3,        );        return isset( $map[ $type ] ) ? $map[ $type ] : 0;    }    // ═══════════════════════════════════════    // ENFORCE BEFORE PUBLISH    // ═══════════════════════════════════════    /**     * Enforce declaration before publishing via JavaScript.     */    public function enforce_declaration_js(): void {        $screen = get_current_screen();        if ( ! $screen ) {            return;        }        if ( ! in_array( $screen->base, array( 'post', 'post-new' ), true ) ) {            return;        }        if ( 'attachment' === $screen->post_type ) {            return;        }        $supported = $this->get_supported_post_types();        if ( ! in_array( $screen->post_type, $supported, true ) ) {            return;        }        ?>        <script>        (function($) {            $(document).ready(function() {                var $publish = $('#publish');                $publish.on('click', function(e) {                    var $checked = $('input[name="megagovern_declaration"]:checked');                    if ($checked.length === 0) {                        e.preventDefault();                        e.stopPropagation();                        $('#megagovern-publish-notice').remove();                        var notice = '<div id="megagovern-publish-notice" class="notice notice-error" style="margin:10px 0;padding:8px 12px;">' +                            '<p><strong><?php echo esc_js( __( 'EU AI Act Declaration required.', 'megagovern' ) ); ?></strong> ' +                            '<?php echo esc_js( __( 'Please select the content source before publishing (Article 50).', 'megagovern' ) ); ?></p>' +                            '</div>';                        $('#post-body-content').before(notice);                        $('#megagovern_declaration').get(0).scrollIntoView({behavior:'smooth'});                        $('#megagovern_declaration').css('box-shadow','0 0 0 2px #d63638');                        setTimeout(function() {                            $('#megagovern_declaration').css('box-shadow','');                        }, 2000);                        return false;                    }                });            });        })(jQuery);        </script>        <?php    }    // ═══════════════════════════════════════    // HELPERS    // ═══════════════════════════════════════    /**     * Get translated label for a declaration type.     *     * @param string $type Declaration type.     * @return string Translated label.     */    public static function get_label( string $type ): string {        return self::get_type_label( $type );    }    /**     * Get icon for a declaration type.     *     * @param string $type Declaration type.     * @return string Icon name.     */    public static function get_icon( string $type ): string {        return isset( self::TYPE_ICONS[ $type ] ) ? self::TYPE_ICONS[ $type ] : 'lucide-file-question';    }    /**     * Get color for a declaration type.     *     * @param string $type Declaration type.     * @return string Color hex.     */    public static function get_color( string $type ): string {        return isset( self::TYPE_COLORS[ $type ] ) ? self::TYPE_COLORS[ $type ] : '#646970';    }    /**     * Get CSS class for a declaration type.     *     * @param string $type Declaration type.     * @return string CSS class.     */    public static function get_css_class( string $type ): string {        return isset( self::TYPE_CSS[ $type ] ) ? self::TYPE_CSS[ $type ] : '';    }    /**     * Get SVG key for a declaration type.     *     * @param string $type Declaration type.     * @return string SVG key.     */    public static function get_svg_key( string $type ): string {        return isset( self::TYPE_SVG[ $type ] ) ? self::TYPE_SVG[ $type ] : '';    }    /**     * Check if a declaration type is valid.     *     * @param string $type Declaration type.     * @return bool True if valid.     */    public static function is_valid( string $type ): bool {        return in_array( $type, self::VALID_TYPES, true );    }    /**     * Get all valid declaration types.     *     * @return array     */    public static function get_valid_types(): array {        return self::VALID_TYPES;    }    /**     * Get content hash for a post.     *     * @param int $post_id Post ID.     * @return string Content hash.     */    public static function get_content_hash( int $post_id ): string {        return get_post_meta( $post_id, '_megagovern_content_hash', true );    }}